ebp","alt":"Không gian sống thoáng sáng với lưới chống muỗi gần như vô hình","position":"50% 50%","mobilePosition":"68% 50%","tone":"result"}}]},{"id":"home-marquee","enabled":true,"type":"marquee","text":"SỢI THỦY TINH CAO CẤP • MAY ĐO VỪA KHÍT • BẢO VỆ VÔ HÌNH • SẠCH BÓNG CÔN TRÙNG •","ariaLabel":"Cam kết chất lượng Rèm Vina"},{"id":"home-benefits","enabled":true,"type":"benefits","eyebrow":"(02) Lợi ích cốt lõi","intro":"Bốn cam kết làm nên trải nghiệm Rèm Vina — từ vật liệu, độ vừa khít đến dịch vụ lắp đặt trọn gói.","title":"Giữ nhà thoáng, sạch và yên tĩnh.","cardKicker":"Cam kết Rèm Vina","cursorLabel":"Khám phá","items":[{"id":"fiberglass","title":"Sợi thủy tinh cao cấp","description":"Sợi thủy tinh bọc PVC chuyên dụng, bền bỉ khi uốn gập và giữ form tốt trong điều kiện khí hậu nóng ẩm.","image":{"src":"/assets/fiberglass-mesh.webp","alt":"Sợi thủy tinh bọc PVC"},"iconKey":"waves"},{"id":"tailored","title":"May đo vừa khít","description":"Từng bộ lưới được cắt may theo kích thước thực tế của khung, hạn chế hở mép và giữ tổng thể gọn gàng.","image":{"src":"/assets/process-measure.webp","alt":"Đo khung cửa để may lưới"},"iconKey":"ruler"},{"id":"protection","title":"Bảo vệ vô hình","description":"Mắt lưới mảnh giúp chống muỗi, giảm côn trùng bay vào nhà mà vẫn giữ tầm nhìn và ánh sáng tự nhiên.","image":{"src":"/assets/threat-mesh.webp","alt":"Lưới chống muỗi gần như vô hình"},"iconKey":"shield"},{"id":"installation","title":"Lắp đặt tận nơi","description":"Đội ngũ kỹ thuật đo, tư vấn, lắp và nghiệm thu tại nhà để sản phẩm sẵn sàng sử dụng ngay.","image":{"src":"/assets/process-install.webp","alt":"Lắp đặt lưới chống muỗi tại nhà"},"iconKey":"home"}]},{"id":"home-craft-process","enabled":true,"type":"craftProcess","eyebrow":"(03) Quy trình may đo","title":"Từ số đo thật đến lớp bảo vệ gần như vô hình.","intro":"Một quy trình liền mạch để từng tấm lưới vừa khít khung cửa, dễ sử dụng và giữ nguyên cảm giác thoáng sáng của ngôi nhà.","steps":[{"id":"measure","eyebrow":"Khảo sát","title":"Đo đúng từ khung cửa thật.","description":"Chiều rộng, chiều cao và những gờ nổi đều được ghi lại để lớp lưới phủ kín mép cửa mà không vướng tay nắm hay ray trượt.","image":{"src":"/assets/process-measure.webp","alt":"Kỹ thuật viên đo khung cửa nhôm trước khi may lưới chống muỗi"}},{"id":"craft","eyebrow":"Chế tác","title":"May viền theo từng milimét.","description":"Mỗi bộ lưới được cắt, may và kiểm tra thủ công để đường viền ôm sát bề mặt dán, giữ tấm lưới phẳng và gọn nhẹ.","image":{"src":"/assets/process-craft.webp","alt":"Cận cảnh thao tác may viền lưới chống muỗi thủ công"}},{"id":"finish","eyebrow":"Hoàn thiện","title":"Lắp gọn, giữ trọn ánh sáng.","description":"Kỹ thuật viên hoàn thiện tại nhà, kiểm tra độ kín và hướng dẫn tháo vệ sinh để không gian luôn thoáng sáng sau khi bàn giao.","image":{"src":"/assets/process-install.webp","alt":"Lưới chống muỗi hoàn thiện trên cửa đi mở ra ban công xanh"}}]},{"id":"home-bento-details","enabled":true,"type":"bentoDetails","eyebrow":"(04) Chi tiết kỹ thuật","title":"Kỹ thuật may đo cho khung cửa Việt.","material":{"title":"Sợi thủy tinh siêu mảnh","description":"Lưới được dệt từ sợi thủy tinh bọc PVC chuyên dụng, đàn hồi tốt và giữ bề mặt ổn định sau thời gian dài sử dụng.","image":{"src":"/assets/fiberglass-mesh.webp","alt":"Cận cảnh sợi thủy tinh bọc PVC"}},"stats":[{"id":"toxic","value":0,"decimals":0,"suffix":"%","fallback":"","label":"Chất độc hại"},{"id":"protection","value":99.9,"decimals":1,"suffix":"%","fallback":"","label":"Chống muỗi"},{"id":"durability","value":10,"decimals":0,"suffix":"+","fallback":"","label":"Năm độ bền"},{"id":"airflow","value":null,"decimals":0,"suffix":"","fallback":"∞","label":"Luồng gió"}],"features":[{"id":"border","title":"Viền dán gọn","description":"Đường viền mảnh, ôm khung và dễ tháo vệ sinh khi cần."},{"id":"same-day","title":"Lắp trong ngày","description":"Kỹ thuật viên đo, tư vấn và hoàn thiện theo lịch hẹn tại nhà."}],"standards":{"title":"Đạt chuẩn cho không gian sống hiện đại","description":"Vật liệu chống tia UV, hạn chế rách và an toàn cho gia đình có trẻ nhỏ hoặc thú cưng.","image":{"src":"/assets/window-mosquito-net-hero.webp","alt":"Lưới chống muỗi lắp trên cửa sổ hiện đại"}}},{"id":"home-horizontal-gallery","enabled":true,"type":"horizontalGallery","eyebrow":"(05) Lối sống","cursorLabel":"Xem","titleLines":["Không Gian","Tuyệt Đỉnh"],"items":[{"id":"living","title":"Phòng khách mở sáng","meta":"Cửa sổ lớn","image":{"src":"/assets/gallery_1.webp","alt":"Phòng khách mở sáng"}},{"id":"rest","title":"Góc nghỉ yên tĩnh","meta":"Lưới gần như vô hình","image":{"src":"/assets/gallery_2.webp","alt":"Góc nghỉ yên tĩnh"}},{"id":"kitchen","title":"Không gian bếp sạch","meta":"Hạn chế côn trùng","image":{"src":"/assets/gallery_3.webp","alt":"Không gian bếp sạch"}},{"id":"breeze","title":"Đón gió tự nhiên","meta":"Không che tầm nhìn","image":{"src":"/assets/lifestyle_breeze.webp","alt":"Đón gió tự nhiên"}}]},{"id":"home-measurement-guide","enabled":true,"type":"measurementGuide","eyebrow":"(06) Cách đo","title":"Chuẩn xác từ số đo đầu tiên.","intro":"Chỉ ba bước ngắn để đội ngũ có đủ thông tin may đúng ngay từ lần đầu tiên.","image":{"src":"/assets/window-mosquito-net-hero.webp","alt":"Khung cửa sổ dùng để minh họa cách đo lưới chống muỗi"},"figureEyebrow":"Bản đo trực quan","idleLabel":"Chọn một bước đo","contentEyebrow":"Đo phủ bì / đơn vị milimét","contentTitle":"Một đường đo liền mạch, không trừ hao.","contentDescription":"Đo mép ngoài của khung giúp lớp lưới che kín toàn bộ điểm tiếp giáp, giữ bề mặt phẳng và không để lại khe hở nhỏ.","steps":[{"id":"width","code":"R","shortLabel":"Chiều rộng phủ bì","title":"01. Đo chiều rộng","description":"Đo từ mép ngoài cùng bên trái sang mép ngoài cùng bên phải của khung cửa. Ghi số đo theo milimet để thợ may căn chính xác.","overlayLabel":"Rộng (R)"},{"id":"height","code":"C","shortLabel":"Chiều cao phủ bì","title":"02. Đo chiều cao","description":"Đo từ mép ngoài phía trên xuống mép ngoài phía dưới. Nên đo ở hai vị trí nếu khung cửa cũ hoặc không đều.","overlayLabel":"Cao (C)"},{"id":"photo","code":"Ảnh","shortLabel":"Gửi toàn cảnh khung","title":"03. Gửi hình khung cửa","description":"Gửi kèm ảnh tổng thể và ảnh cận mép khung để đội ngũ tư vấn chọn kiểu viền phù hợp trước khi sản xuất.","overlayLabel":"Chụp trọn khung cửa"}]},{"id":"home-faq","enabled":true,"type":"faq","eyebrow":"(07) Câu hỏi thường gặp","backdropLabel":"HỎI","title":"Trước khi đặt may.","intro":"Những điều khách hàng thường hỏi trước khi gửi số đo và chọn kiểu viền phù hợp cho từng khung cửa.","cta":{"label":"Cần tư vấn riêng","href":"#order","cursorLabel":"Liên hệ"},"items":[{"id":"included-border","question":"Kích thước có bao gồm phần viền không?","answer":"Có. Kích thước sản xuất là kích thước phủ bì, đã tính cả phần viền dán. Bạn chỉ cần đo mép ngoài cùng của khung cửa."},{"id":"inside-outside","question":"Nên đo bên trong hay bên ngoài khung?","answer":"Hãy đo cạnh ngoài của khung để lưới che phủ toàn bộ mép cửa. Nếu khung có gờ hoặc tay nắm đặc biệt, gửi thêm ảnh để được tư vấn."},{"id":"natural-light","question":"Lưới có làm tối nhà không?","answer":"Không. Mắt lưới mảnh nên vẫn giữ ánh sáng tự nhiên và tầm nhìn thoáng khi nhìn từ khoảng cách sinh hoạt thông thường."},{"id":"large-opening","question":"Có nhận may kích thước cửa lớn không?","answer":"Có. Đội ngũ có thể tư vấn phương án chia tấm hoặc may khổ lớn tùy cấu trúc cửa để hạn chế nhăn, võng và hở mép."}]},{"id":"home-footer-cta","enabled":true,"type":"footerCta","eyebrow":"(08) Điểm chạm cuối","kicker":"May đo cho chính khung cửa của bạn","title":{"prefix":"Bắt đầu một","accent":"không gian thoáng hơn."},"email":"tuvan@remvina.vn","emailLabel":"tuvan@remvina.vn","cursorLabel":"Đặt may","copyright":"© 2026 Rèm Vina. Bản quyền đã được bảo hộ.","backToTopLabel":"Lên đầu trang","backToTopCursorLabel":"Lên đầu","socialCursorLabel":"Mở","socialLabels":{"facebook":"Facebook","shopee":"Shopee"}}]',
  'published',
  'Rèm Vina — Lưới chống muỗi may đo',
  'Lưới chống muỗi cao cấp may đo theo từng khung cửa, giữ nhà thoáng sáng và bảo vệ gia đình.',
  1,
  'seed',
  cast(unixepoch('subsecond') * 1000 as integer),
  cast(unixepoch('subsecond') * 1000 as integer)
);

INSERT OR IGNORE INTO page_revisions (
  id,
  page_id,
  version,
  snapshot,
  note,
  created_by,
  created_at
)
SELECT
  'seed-revision-page-home',
  id,
  version,
  json_object(
    'title', title,
    'slug', slug,
    'template', template,
    'blocks', json(blocks),
    'seoTitle', seo_title,
    'seoDescription', seo_description,
    'canonicalUrl', canonical_url,
    'ogImage', og_image,
    'robotsIndex', json(CASE WHEN robots_index = 1 THEN 'true' ELSE 'false' END),
    'robotsFollow', json(CASE WHEN robots_follow = 1 THEN 'true' ELSE 'false' END)
  ),
  'Initial published homepage seed',
  'seed',
  updated_at
FROM pages
WHERE id = 'seed-page-home' AND published_revision_id IS NULL;

UPDATE pages
SET
  published_revision_id = 'seed-revision-page-home',
  published_at = COALESCE(published_at, updated_at),
  updated_by = CASE WHEN updated_by = '' THEN 'seed' ELSE updated_by END
WHERE id = 'seed-page-home' AND published_revision_id IS NULL;

